const lyricMessageOrigin = (() => {
    try {
        const origin = window.parent.location.origin;
        if (origin && origin !== "null") return origin;
    } catch (e) {}
    try {
        const origin = new URL(document.referrer).origin;
        if (origin && origin !== "null") return origin;
    } catch (e) {}
    return "*";
})();
const lyricMessageOriginMatches = (origin) => lyricMessageOrigin === "*" || origin === lyricMessageOrigin;
let isManualScrolling = false, scrollTimer = null, manualMovePx = 0, musicObj = [], currentTime = 0, currentIndex = 0, anim = false, 
threadId = "frs", lastReportedIndex = -1;
let domData = { ul: document.querySelector(".container ul"), container: document.querySelector(".container") };
const hasTime = () => musicObj.some(m => m.time >= 0);
const decodeMetaEntities = (text) => String(text || '').replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (full, code) => { const lower = code.toLowerCase(); if (lower === 'amp') return '&'; if (lower === 'lt') return '<'; if (lower === 'gt') return '>'; if (lower === 'quot') return '"'; if (lower === 'apos') return "'"; const value = lower.startsWith('#x') ? parseInt(lower.slice(2), 16) : parseInt(lower.slice(1), 10); return Number.isFinite(value) && value >= 0 && value <= 0x10ffff && !(value >= 0xd800 && value <= 0xdfff) ? String.fromCodePoint(value) : full; });
const isContributorLine = (text) => /^(?:滚动歌词贡献者|翻译歌词贡献者)\s*[:：]/.test(decodeMetaEntities(String(text || '').replace(/\u0001\d+\u0001/g, '').replace(/<[^>]*>?/gm, '').trim()));
const metaTextKey = (text) => decodeMetaEntities(String(text || '')).replace(/\u0001\d+\u0001/g, '').replace(/<[^>]*>?/gm, '').replace(/\s+/g, ' ').trim().replace(/：/g, ':').replace(/\s*:\s*/g, ':').toLocaleLowerCase();
const isMetaText = (text) => /^(?:作词|作曲|编曲|制作人|混音|母带|监制|和声|吉他|贝斯|鼓手|录音|滚动歌词贡献者|翻译歌词贡献者)\s*[:：]/.test(decodeMetaEntities(String(text || '').trim()));
const parseMetaLine = (line) => {
    try {
        const meta = JSON.parse(line.trim());
        if (!Number.isFinite(Number(meta.t)) || !Array.isArray(meta.c)) return null;
        const text = meta.c.reduce((acc, item) => acc + (item && (item.tx !== undefined ? item.tx : item.c)) || '', '');
        if (!text.trim()) return null;
        return { time: Number(meta.t) / 1000, text, isMeta: true, isContributor: isContributorLine(text) };
    } catch (e) { return null; }
};
const getMusicIndex = () => {
    let index = -1;
    for (let i = 0; i < musicObj.length; i++) {
        if (musicObj[i].time >= 0) {
            if (currentTime >= musicObj[i].time) {
                index = i;
            } else {
                break;
            }
        }
    }
    if (index === -1) {
        const firstReal = musicObj.findIndex(m => m.time >= 0);
        return firstReal >= 0 ? firstReal - 1 : 0;
    }
    return index;
};
const matchTranslations = () => {
    if (typeof tlyricData === "undefined" || !tlyricData || tlyricData.length === 0) return;
    let transPool = tlyricData.map(t => ({ ...t, used: false }));
    let potentialPairs = [];
    musicObj.forEach((line, lineIdx) => {
        if (line.time < 0 || line.isMeta) return;
        transPool.forEach((trans, transIdx) => {
            let diff = Math.abs(line.time - trans.time);
            if (diff < 4.0) {
                potentialPairs.push({ lineIdx, transIdx, diff, text: trans.text });
            }
        });
    });
    potentialPairs.sort((a, b) => a.diff - b.diff);
    let matchedLines = new Set();
    let matchedTrans = new Set();
    potentialPairs.forEach(pair => {
        if (matchedLines.has(pair.lineIdx) || matchedTrans.has(pair.transIdx)) return;
        musicObj[pair.lineIdx].translation = pair.text;
        matchedLines.add(pair.lineIdx);
        matchedTrans.add(pair.transIdx);
    });
};
const esc = window.lyricEsc || ((s) => String(s));
const decodeLyricText = (s) => { const area = document.createElement("textarea"); area.innerHTML = String(s); return area.value; };
const renderLyricText = (s) => { const text = esc(decodeLyricText(s)); return window.lyricRestoreImgTokens ? window.lyricRestoreImgTokens(text) : text; };
const addMusic = () => { 
    let frag = document.createDocumentFragment(); musicObj.forEach(m => { let li = document.createElement("li"); li.onclick = (e) => {
        const link = e && e.target && e.target.closest ? e.target.closest(".lyric-creator[data-w]") : null;
        if (link) { window.parent.postMessage({ type: "openUrl", url: link.getAttribute("data-w") }, lyricMessageOrigin); return; }
        if (m.time >= 0) window.parent.postMessage({ type: "seekAudio", time: m.time }, lyricMessageOrigin);
    }; let wrapper = document.createElement("div"); 
    wrapper.className = "lyric-wrapper"; 
    let transHtml = m.translation ? "<div class=\"trans-line\">" + esc(decodeLyricText(m.translation)) + "</div>" : "";
    const orig = (m.text === "‎") ? "&nbsp;" : renderLyricText(m.text);
    wrapper.innerHTML = "<div class=\"orig-line\">" + orig + "</div>" + transHtml; li.appendChild(wrapper); frag.appendChild(li); }); domData.ul.appendChild(frag);};

const syncScrollPosition = () => { 
    if (isManualScrolling || !hasTime()) return; 
    const items = domData.ul.children; 
    let curLi = items[currentIndex]; 
    if (!curLi) return; 
    let movePx = curLi.offsetTop + (curLi.clientHeight / 2) - (domData.container.clientHeight / 2); 
    domData.ul.style.transform = "translateY(-" + movePx + "px)"; };

const move = () => { if (!hasTime()) return; let newIdx = getMusicIndex(); const items = domData.ul.children; 
    if (newIdx !== lastReportedIndex) { 
        lastReportedIndex = newIdx; 
        if (musicObj[newIdx] && musicObj[newIdx].text !== "‎") { const report = window.lyricStripImgTokens ? window.lyricStripImgTokens(musicObj[newIdx].text) : musicObj[newIdx].text; window.parent.postMessage({ type: "lyricUpdate", text: decodeLyricText(report.replace(/<[^>]*>?/gm, "").trim()) }, lyricMessageOrigin); }
        domData.ul.querySelectorAll(".active, .active-noanim").forEach(el => el.classList.remove("active", "active-noanim")); currentIndex = newIdx; 
        let curLi = items[currentIndex]; 
        if (curLi) curLi.classList.add(anim ? "active" : "active-noanim"); 
        syncScrollPosition(); 
    } else { currentIndex = newIdx; } 
    
};

window.addEventListener("wheel", (e) => { isManualScrolling = true; clearTimeout(scrollTimer); const matrix = new WebKitCSSMatrix(window.getComputedStyle(domData.ul).transform); manualMovePx = Math.abs(matrix.m42) + e.deltaY; const maxMove = domData.ul.scrollHeight - domData.container.clientHeight; if (manualMovePx < 0) manualMovePx = 0; if (manualMovePx > maxMove) manualMovePx = maxMove; domData.ul.style.transition = "transform 0.2s ease-out"; domData.ul.style.transform = "translateY(-" + manualMovePx + "px)"; scrollTimer = setTimeout(() => { isManualScrolling = false; if (hasTime()) { domData.ul.style.transition = "transform 0.6s cubic-bezier(0.25, 0.1, 0.2, 1)"; syncScrollPosition(); } }, 5000); }, { passive: true });

window.addEventListener("message", (e) => { 
    if (e.source !== window.parent) return;
    if (!lyricMessageOriginMatches(e.origin)) return;
    if (!e.data || typeof e.data !== 'object') return;
    if (e.data.type === "playTimeResponse") {
        const t = Number(e.data.time);
        if (Number.isFinite(t) && t >= 0) { currentTime = t; move(); }
    } if (e.data.type === "toggleTrans") document.body.classList.toggle("show-trans", e.data.visible); 
    if (e.data.type === "updateColor") document.documentElement.style.setProperty("--active-color", e.data.color);
    if (e.data.type === "updateTransColor") { const c = e.data.color; if (typeof c === "string" && /^#[0-9a-fA-F]{3,8}$/.test(c.trim())) document.documentElement.style.setProperty("--trans-color", c.trim()); }
    if (e.data.type === "updateIdleColor") { const c = e.data.color; if (typeof c === "string" && /^#[0-9a-fA-F]{3,8}$/.test(c.trim())) document.documentElement.style.setProperty("--idle-color", c.trim()); }
    if (e.data.type === "updateTransIdleColor") { const c = e.data.color; if (typeof c === "string" && /^#[0-9a-fA-F]{3,8}$/.test(c.trim())) document.documentElement.style.setProperty("--trans-idle-color", c.trim()); }
});

const init = () => {
    musicObj = (() => { 
        const raw = window.lrc || ""; 
        let lines = raw.split("\n"), res = []; 
        const isT = lines.some(l => /^\s*\[\d{1,3}:\d{2}(?:[.:]\d{1,3})?\]/.test(l));
        if (isT) for (let i = 0; i < 7; i++) res.push({ time: -1, text: "‎" }); 
        const seenMeta = new Set();
        lines.forEach(l => {
            const meta = parseMetaLine(l);
            if (meta) {
                const key = metaTextKey(meta.text);
                if (key && seenMeta.has(key)) return;
                if (key) seenMeta.add(key);
                if (showMeta === false && !meta.isContributor) return;
                if (showContributors === false && meta.isContributor) return;
                res.push(meta);
                return;
            }
            const timePrefix = l.match(/^((?:\[\d{1,3}:\d{2}(?:[.:]\d{1,3})?\]\s*)+)/);
            const matches = timePrefix ? [...timePrefix[1].matchAll(/\[(\d{1,3}):(\d{2})(?:[.:](\d{1,3}))?\]/g)] : [];
            if (matches.length > 0) {
                const lineText = l.slice(timePrefix[1].length).trim();
                matches.forEach(m => {
                    const lineMeta = isMetaText(lineText);
                    const key = metaTextKey(lineText);
                    if (lineMeta && key && seenMeta.has(key)) return;
                    if (lineMeta && key) seenMeta.add(key);
                    if (showMeta === false && lineMeta && !isContributorLine(lineText)) return;
                    if (showContributors === false && isContributorLine(lineText)) return;
                    const msStr = (m[3] || '').padEnd(3, '0');
                    res.push({ time: parseInt(m[1]) * 60 + parseInt(m[2]) + parseInt(msStr) / 1000, text: lineText, isMeta: lineMeta, isContributor: lineMeta && isContributorLine(lineText) });
                });
            }
            else { let txt = l.replace(/\{.*?\}/g, "").trim();
                const lineMeta = isMetaText(txt);
                const contributor = lineMeta && isContributorLine(txt);
                const key = lineMeta ? metaTextKey(txt) : "";
                if (lineMeta && key && seenMeta.has(key)) return;
                if (lineMeta && key) seenMeta.add(key);
                if (showMeta === false && lineMeta && !contributor) return;
                if (showContributors === false && contributor) return;
                if (txt !== "") res.push({ time: 0, text: txt, isMeta: lineMeta, isContributor: contributor });
            } }); 
            if (isT) for (let i = 0; i < 7; i++) res.push({ time: -1, text: "‎" });
            return res; 
        })(); 
        matchTranslations(); 
        addMusic();
        if (!hasTime()) { 
            domData.ul.style.transform = "translateY(0)"; 
            return; 
        }
        requestAnimationFrame(() => { 
            if(!domData.ul.children[0]) return; 
            let startPx = domData.container.clientHeight / 2 - domData.ul.children[0].clientHeight / 2; 
            anim = false; domData.ul.style.transition = "none"; 
            domData.ul.style.transform = "translateY(" + startPx + "px)"; 
            move(); 
            setTimeout(() => { 
                domData.ul.style.transition = "transform 0.6s cubic-bezier(0.25, 0.1, 0.2, 1)"; 
                anim = true; 
            }, 50); 
        }); 
        setInterval(() => window.parent.postMessage({ type: "getPlayTime", id: threadId }, lyricMessageOrigin), 50); };

init(); window.addEventListener("resize", syncScrollPosition); window.addEventListener('click', () => { window.parent.postMessage({ type: 'iframeClick' }, lyricMessageOrigin); });
